export function isCheckoutRequired(cart, summary, service) {
    if (service.bookingPolicy?.cancellationFeePolicy?.enabled) {
        return true;
    }
    const total = Number(summary.priceSummary?.total?.amount ?? 0);
    if (total === 0) {
        return false;
    }
    const paymentOption = cart.lineItems?.[0]?.paymentConfig?.paymentOption;
    if (paymentOption === 'FULL_PAYMENT_OFFLINE') {
        return false;
    }
    return true;
}
